--
-- Struttura della tabella `athletes_inscriptions`
--

CREATE TABLE `athletes_inscriptions` (
  `id` int(11) NOT NULL,
  `athlete_id` int(11) NOT NULL,
  `category_code_id` smallint(6) NOT NULL,
  `competition_id` smallint(6) NOT NULL,
  `cintura` varchar(50) DEFAULT NULL,
  `n_iscrizione` smallint(6) DEFAULT NULL,
  `inviato` tinyint(4) NOT NULL DEFAULT 0,
  `modificato` tinyint(4) NOT NULL DEFAULT 0,
  `accorpamento` tinyint(4) NOT NULL DEFAULT 0,
  `old_category` varchar(15) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

