--
-- Struttura della tabella `category_codes`
--

CREATE TABLE `category_codes` (
  `id` int(6) NOT NULL,
  `codice` varchar(10) NOT NULL,
  `categoria` varchar(50) NOT NULL,
  `anno_min` int(4) NOT NULL,
  `anno_max` int(4) NOT NULL,
  `sesso` text NOT NULL,
  `grado` varchar(300) NOT NULL,
  `cat_peso` varchar(10) DEFAULT NULL,
  `peso_min` int(5) DEFAULT NULL,
  `peso_max` int(5) DEFAULT NULL,
  `specialita` varchar(100) NOT NULL,
  `costo_intero` float NOT NULL,
  `costo_scontato` float NOT NULL,
  `codiceTipoCategorie` smallint(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_bin ROW_FORMAT=COMPACT;

